mapper.select:
select from cost_boq_compare c left join cost_boq_item li on li.id = c.left_item_id and li.del_flag = '0' left join cost_boq_item ri on ri.id = c.right_item_id and ri.del_flag = '0' where c.del_flag = '0' and c.project_id = #{projectId} and c.left_batch_id = #{leftBatchId} and c.right_batch_id = #{rightBatchId}
and c.match_type = #{matchType}
and (li.item_code like concat('%', #{keyword}, '%') or li.item_name like concat('%', #{keyword}, '%') or ri.item_code like concat('%', #{keyword}, '%') or ri.item_name like concat('%', #{keyword}, '%'))
order by coalesce(li.source_row, ri.source_row) asc, c.id asc

select count(1) from cost_boq_compare
where del_flag = '0' and project_id = #{projectId}
  and left_batch_id = #{leftBatchId} and right_batch_id = #{rightBatchId}

mapper.update:
update cost_boq_compare set del_flag = '2', update_by = #{updateBy}, update_time = sysdate()
where del_flag = '0' and project_id = #{projectId}
  and left_batch_id = #{leftBatchId} and right_batch_id = #{rightBatchId}
  and match_type != 'MANUAL'

update cost_boq_compare set del_flag = '2', update_by = #{updateBy}, update_time = sysdate()
where del_flag = '0' and project_id = #{projectId}
  and left_batch_id = #{leftBatchId} and right_batch_id = #{rightBatchId}
  and match_type in ('ONLY_LEFT','ONLY_RIGHT')

update cost_boq_compare set del_flag = '2', update_by = #{updateBy}, update_time = sysdate()
where del_flag = '0' and project_id = #{projectId}
  and left_batch_id = #{leftBatchId} and right_batch_id = #{rightBatchId}
  and (left_item_id = #{leftItemId} or right_item_id = #{rightItemId})
